<?php require __DIR__.'/../includes/bootstrap.php'; admin_required();$services=db()->query('SELECT id,name FROM services WHERE active=1 ORDER BY name')->fetchAll();
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$action=$_POST['action']??'save';if($action==='toggle'){db()->prepare('UPDATE packages SET active=1-active WHERE id=?')->execute([(int)$_POST['id']]);}else{$id=(int)($_POST['id']??0);$vals=[trim($_POST['name']),trim($_POST['description'])?:null,(float)str_replace(',','.',$_POST['price']),(int)$_POST['validity_days'],isset($_POST['featured'])];if($id){db()->prepare('UPDATE packages SET name=?,description=?,price=?,validity_days=?,featured=? WHERE id=?')->execute([...$vals,$id]);$pid=$id;}else{db()->prepare('INSERT INTO packages(name,description,price,validity_days,featured) VALUES (?,?,?,?,?)')->execute($vals);$pid=(int)db()->lastInsertId();}db()->prepare('DELETE FROM package_services WHERE package_id=?')->execute([$pid]);foreach($_POST['qty']??[] as $sid=>$qty){$qty=(int)$qty;if($qty>0)db()->prepare('INSERT INTO package_services(package_id,service_id,quantity) VALUES (?,?,?)')->execute([$pid,(int)$sid,$qty]);}}header('Location: packages.php');exit;}
$packages=db()->query("SELECT p.*,GROUP_CONCAT(CONCAT(ps.quantity,'x ',s.name) SEPARATOR ' • ') included FROM packages p LEFT JOIN package_services ps ON ps.package_id=p.id LEFT JOIN services s ON s.id=ps.service_id GROUP BY p.id ORDER BY p.id DESC")->fetchAll();
?><!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Pacotes | PG Estética</title><link rel="stylesheet" href="../assets/css/style.css"></head><body class="admin-shell"><?php include '_nav.php'; ?><section><div class="container"><span class="eyebrow">ofertas e recorrência</span><h1>Pacotes promocionais</h1><div class="two-col"><div class="panel"><h2>Novo pacote</h2><form method="post"><input type="hidden" name="csrf" value="<?= e(csrf_token()) ?>"><label>Nome</label><input name="name" required><label>Descrição</label><textarea name="description"></textarea><div class="row"><div><label>Preço</label><input name="price" required></div><div><label>Validade (dias)</label><input type="number" name="validity_days" value="90" min="1"></div></div><h3>Sessões incluídas</h3><?php foreach($services as $s): ?><div class="qty-row"><span><?= e($s['name']) ?></span><input type="number" min="0" name="qty[<?= $s['id'] ?>]" value="0"></div><?php endforeach; ?><label class="checkline"><input type="checkbox" name="featured"> Destacar no site</label><button class="btn btn-primary">Criar pacote</button></form></div><div class="panel"><h2>Pacotes cadastrados</h2><?php foreach($packages as $p): ?><div class="package-admin"><div><strong><?= e($p['name']) ?></strong> · <?= money((float)$p['price']) ?><br><span class="small muted"><?= e($p['included']) ?></span></div><form method="post"><input type="hidden" name="csrf" value="<?= e(csrf_token()) ?>"><input type="hidden" name="action" value="toggle"><input type="hidden" name="id" value="<?= (int)$p['id'] ?>"><button class="btn btn-small <?= $p['active']?'btn-outline':'btn-primary' ?>"><?= $p['active']?'Desativar':'Ativar' ?></button></form></div><?php endforeach; ?></div></div></div></section></body></html>
